import{_ as t,o as a,c as n,ag as i}from"./chunks/framework.CxkNbRKf.js";const o="/nada-documentation/images/image71.png",s="/nada-documentation/images/image72.png",r="/nada-documentation/images/image73.png",l="/nada-documentation/images/image74.png",c="/nada-documentation/images/image75.png",d="/nada-documentation/images/image76.png",w=JSON.parse('{"title":"Countries","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/countries.md","filePath":"admin-guide/web-ui/countries.md","lastUpdated":1786379412000}'),u={name:"admin-guide/web-ui/countries.md"};function m(p,e,h,g,f,y){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="countries" tabindex="-1">Countries <a class="header-anchor" href="#countries" aria-label="Permalink to &quot;Countries&quot;">​</a></h1><p><img src="'+o+'" alt=""> Most entries in a data catalog will relate to one or multiple countries. All metadata standards and schemas used by NADA include an element to capture this information:</p><ul><li><p>&#39;nation&#39; in the DDI Codebook;</p></li><li><p>&#39;geographic_units&#39; in the time series schema;</p></li><li><p>&#39;ref_country&#39; in the Dublin Core/document schema and in the tables schema;</p></li><li><p>&#39;locationsShown/countryName&#39; in the IPTC schema for images;</p></li><li><p>&#39;country&#39; in the video schema.</p></li></ul><p>This information, especially in multi-country catalogs, is particularly relevant to filter data. By default, NADA provides a facet to filter entries by country.</p><p>But countries can be named in different manners in datasets/metadata. For example, the Democratic Republic of Congo could also be referred to as &quot;DR Congo&quot;, &quot;Congo, DR&quot;, &quot;DRC&quot;. Multiple variants of a country name should all be mapped to a unique label, for two reasons:</p><ul><li><p>It would be inconvenient to users of a catalog to have to select more than one item in a list to identify entries related to one single country.</p></li><li><p>It can be politically important (and a requirement) for some organizations to comply with specific names for countries and territories.</p></li></ul><p>To address this issue, catalog administrators can provide their instance of NADA with a reference list of countries and capture the alternative names that may be found in the metadata. Note that &quot;countries&quot; can be &quot;territories&quot;, &quot;economies&quot;, &quot;regions&quot;, or groups of countries. A default list of country names is provided in the NADA application, which can be edited.</p><h2 id="using-the-administrator-interface" tabindex="-1">Using the administrator interface <a class="header-anchor" href="#using-the-administrator-interface" aria-label="Permalink to &quot;Using the administrator interface&quot;">​</a></h2><p><img src="'+s+'" alt=""></p><p>To add a new country, click &quot;Add new country&quot;. To edit a country, click on &quot;Edit&quot;. In both cases, you will be taken to a form where the country name to be used as the reference, its code (ISO, or possibly other), and the variants of the country name (aliases), can be entered or edited.</p><p><img src="'+r+'" alt=""></p><p>The list of countries entered in this list will serve as a control list for metadata entered in NADA. When metadata are imported and contain non-compliant names, these non-compliant names will be flagged in the entry page (displayed with red background). In the example below, &quot;Cabo Verde&quot; for example is flagged because the reference list of countries only recognizes the name &quot;Cape Verde&quot;. Ideally, these issues should be fixed.</p><p>The names do NOT have to be fixed by changing the metadata themselves. In some cases, it would make sense to do so, but in others it could create inconsistencies between the source data and the metadata. The solution to address the issue when the data/metadata cannot be changed is to map non-compliant names to names found in the reference list. The fixes (i.e. the aliases for country names) will be stored, so the chances of finding non-compliant names in metadata is likely to rapidly reduce over time.</p><p><img src="'+l+'" alt=""></p><p>Clicking on any flagged name, or on the main menu item Settings &gt; Countries, will open the page where the mappings can be done. In that page, click on &quot;Country mappings&quot;.</p><p><img src="'+c+'" alt=""></p><p>This will open a table showing the list of non-compliant country names. For each one of them, you can select a country from the list of compliant countries, then click &quot;Update&quot;. The non-compliant name will now be stored as an alias which will be applied automatically to other datasets that may have used the same non-compliant name. This line of the table will disappear when refreshing the page.</p><p>If you do not find an equivalent in the reference list, you may consider adding it. This is however not a requirement. Metadata with non-compliant country names can be stored in the application. The main impact is that they will not be identified in the filter by country (facet), which only shows the countries found in the reference list as options.</p><p><img src="'+d+'" alt=""></p><p>Warning: if you delete a country ...</p><h2 id="using-the-api" tabindex="-1">Using the API <a class="header-anchor" href="#using-the-api" aria-label="Permalink to &quot;Using the API&quot;">​</a></h2><p>Uploading and maintaining a list of countries</p><p>R</p><p>Python</p>',24)])])}const q=t(u,[["render",m]]);export{w as __pageData,q as default};
